-- Written by internal/node/testdata/releases/gen_test.go.txt (scripts/release-db.sh).
CREATE TABLE agents (
  id TEXT PRIMARY KEY, label TEXT NOT NULL, harness TEXT NOT NULL, cwd TEXT NOT NULL,
  first_seen_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL);
CREATE TABLE cursors (
  agent TEXT NOT NULL, room TEXT NOT NULL, author TEXT NOT NULL, epoch TEXT NOT NULL,
  start INTEGER NOT NULL, pos INTEGER NOT NULL,
  PRIMARY KEY (agent, room, author, epoch));
CREATE TABLE file_copies (
  room TEXT NOT NULL, msg TEXT NOT NULL, sha256 TEXT NOT NULL, agent TEXT NOT NULL, path TEXT NOT NULL,
  state TEXT NOT NULL, size INTEGER NOT NULL, tmp TEXT NOT NULL DEFAULT '', ident TEXT NOT NULL DEFAULT '', PRIMARY KEY (room, path));
CREATE TABLE file_for (
  room TEXT NOT NULL, sha256 TEXT NOT NULL, msg TEXT NOT NULL, how TEXT NOT NULL,
  PRIMARY KEY (room, sha256, msg));
CREATE TABLE file_items (
  room TEXT NOT NULL, record TEXT NOT NULL, n INTEGER NOT NULL, sha256 TEXT NOT NULL,
  name TEXT NOT NULL, size INTEGER NOT NULL, type TEXT NOT NULL,
  PRIMARY KEY (room, record, n));
CREATE TABLE file_lists (
  room TEXT NOT NULL, record TEXT NOT NULL, state TEXT NOT NULL, fails INTEGER NOT NULL DEFAULT 0,
  next_at INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (room, record));
CREATE TABLE file_obs (
  room TEXT NOT NULL, msg TEXT NOT NULL, sha256 TEXT NOT NULL, peer TEXT NOT NULL, answer TEXT NOT NULL,
  at INTEGER NOT NULL, PRIMARY KEY (room, msg, sha256, peer));
CREATE TABLE file_parts (
  room TEXT NOT NULL, msg TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL, have INTEGER NOT NULL,
  at INTEGER NOT NULL, PRIMARY KEY (room, msg, sha256));
CREATE TABLE file_sets (
  room TEXT NOT NULL, record TEXT NOT NULL, manifest TEXT NOT NULL, ok INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (room, record));
CREATE TABLE file_trash (
  path TEXT PRIMARY KEY, at INTEGER NOT NULL, kind TEXT NOT NULL, room TEXT NOT NULL DEFAULT '',
  msg TEXT NOT NULL DEFAULT '', sha256 TEXT NOT NULL DEFAULT '', size INTEGER NOT NULL DEFAULT 0, ident TEXT NOT NULL DEFAULT '', unlinked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE file_wants (
  room TEXT NOT NULL, msg TEXT NOT NULL, version TEXT NOT NULL, sha256 TEXT NOT NULL, author TEXT NOT NULL,
  size INTEGER NOT NULL, at INTEGER NOT NULL, tries INTEGER NOT NULL DEFAULT 0, lapsed_at INTEGER NOT NULL DEFAULT 0,
  list INTEGER NOT NULL DEFAULT 0, sent_at INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (room, msg, sha256));
CREATE TABLE files (
  room TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL, state TEXT NOT NULL,
  PRIMARY KEY (room, sha256));
CREATE TABLE forks (
  room TEXT NOT NULL, author TEXT NOT NULL, epoch TEXT NOT NULL, seq INTEGER NOT NULL,
  id TEXT NOT NULL, hdr BLOB NOT NULL, sig BLOB NOT NULL, at INTEGER NOT NULL,
  PRIMARY KEY (room, id));
CREATE TABLE joins (
  invite TEXT PRIMARY KEY, room TEXT NOT NULL, label TEXT NOT NULL, create_id TEXT NOT NULL,
  role TEXT NOT NULL, history INTEGER NOT NULL, member INTEGER NOT NULL, admin TEXT NOT NULL, addrs TEXT NOT NULL,
  gen INTEGER NOT NULL, expires_at INTEGER NOT NULL, state TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, pinned_gen INTEGER NOT NULL DEFAULT 0);
CREATE TABLE levels (
  agent TEXT NOT NULL, room TEXT NOT NULL, level TEXT NOT NULL,
  PRIMARY KEY (agent, room));
CREATE TABLE log (
  room TEXT NOT NULL, id TEXT NOT NULL, author TEXT NOT NULL, seq INTEGER NOT NULL,
  bytes BLOB NOT NULL, sig BLOB NOT NULL, state TEXT NOT NULL, reason TEXT NOT NULL,
  batch INTEGER NOT NULL, batch_pos INTEGER NOT NULL, arrival INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (room, id));
CREATE TABLE meta (key TEXT PRIMARY KEY, value INTEGER NOT NULL);
CREATE TABLE observed (
  room TEXT NOT NULL, peer TEXT NOT NULL, author TEXT NOT NULL,
  digest TEXT NOT NULL, detail TEXT, at INTEGER NOT NULL,
  PRIMARY KEY (room, peer, author));
CREATE TABLE peer_addrs (
  node TEXT NOT NULL, addr TEXT NOT NULL, source TEXT NOT NULL,
  seen_at INTEGER NOT NULL, failed_at INTEGER NOT NULL DEFAULT 0, fails INTEGER NOT NULL DEFAULT 0,
  good INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (node, addr));
CREATE TABLE read_heads (
  agent TEXT NOT NULL, room TEXT NOT NULL, author TEXT NOT NULL, record TEXT NOT NULL,
  PRIMARY KEY (agent, room, author, record));
CREATE TABLE reads (
  agent TEXT NOT NULL, room TEXT NOT NULL, key TEXT NOT NULL, version TEXT NOT NULL,
  msg TEXT NOT NULL,
  PRIMARY KEY (agent, room, key));
CREATE TABLE records (
  room TEXT NOT NULL, id TEXT NOT NULL, author TEXT NOT NULL, epoch TEXT NOT NULL,
  seq INTEGER NOT NULL, kind TEXT NOT NULL, ref TEXT NOT NULL, parent TEXT NOT NULL,
  thread TEXT NOT NULL, agent TEXT NOT NULL, created INTEGER NOT NULL,
  hdr BLOB NOT NULL, sig BLOB NOT NULL, body BLOB,
  reason TEXT NOT NULL, effect TEXT NOT NULL,
  PRIMARY KEY (room, id), UNIQUE (room, author, epoch, seq));
CREATE TABLE refusals (
  room TEXT NOT NULL, peer TEXT NOT NULL, reason TEXT NOT NULL,
  count INTEGER NOT NULL, last_at INTEGER NOT NULL,
  PRIMARY KEY (room, peer, reason));
CREATE TABLE registrations (agent TEXT PRIMARY KEY, at INTEGER NOT NULL);
CREATE TABLE requests (
  id TEXT PRIMARY KEY, kind TEXT NOT NULL, room TEXT NOT NULL, node TEXT NOT NULL,
  name TEXT NOT NULL, role TEXT NOT NULL, action TEXT NOT NULL, history INTEGER NOT NULL, seconds TEXT NOT NULL,
  created_at INTEGER NOT NULL, state TEXT NOT NULL, decided_at INTEGER NOT NULL DEFAULT 0,
  entries TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', admins INTEGER NOT NULL DEFAULT 0, not_caught_up INTEGER NOT NULL DEFAULT 0, draft TEXT NOT NULL DEFAULT '', terms TEXT NOT NULL DEFAULT '');
CREATE TABLE room_files (room TEXT PRIMARY KEY, mode TEXT NOT NULL, decided_at INTEGER NOT NULL);
CREATE TABLE room_invites (
  secret_hash TEXT PRIMARY KEY, room TEXT NOT NULL, role TEXT NOT NULL, history INTEGER NOT NULL,
  created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, bound_key TEXT NOT NULL DEFAULT '',
  name TEXT NOT NULL DEFAULT '', addrs TEXT NOT NULL DEFAULT '[]',
  state TEXT NOT NULL, request TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '',
  shown_member INTEGER NOT NULL DEFAULT 0, shown_role TEXT NOT NULL DEFAULT '', shown_history INTEGER NOT NULL DEFAULT 0);
CREATE TABLE room_members (
  room TEXT NOT NULL, node TEXT NOT NULL, member INTEGER NOT NULL, admin INTEGER NOT NULL,
  admitted INTEGER NOT NULL, name TEXT NOT NULL, addrs TEXT NOT NULL DEFAULT '[]',
  seen_at INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (room, node));
CREATE TABLE rooms (
  id TEXT PRIMARY KEY, label TEXT NOT NULL, create_id TEXT NOT NULL DEFAULT '', gen INTEGER NOT NULL DEFAULT 0, joined_at INTEGER NOT NULL DEFAULT 0, left_at INTEGER NOT NULL DEFAULT 0, arrivals INTEGER NOT NULL DEFAULT 0);
CREATE TABLE shown (
  agent TEXT NOT NULL, room TEXT NOT NULL, key TEXT NOT NULL, version TEXT NOT NULL, msg TEXT NOT NULL,
  PRIMARY KEY (agent, room, key));
CREATE TABLE skips (
  agent TEXT NOT NULL, room TEXT NOT NULL, msg TEXT NOT NULL,
  PRIMARY KEY (agent, room, msg));
CREATE TABLE streams (
  room TEXT NOT NULL, author TEXT NOT NULL, epoch TEXT NOT NULL,
  contig INTEGER NOT NULL, known INTEGER NOT NULL DEFAULT 0, known_at INTEGER NOT NULL DEFAULT 0, known_from TEXT NOT NULL DEFAULT '',
  PRIMARY KEY (room, author, epoch));
